  expect_identical(.pyrun(local({ t <- character_table(get_perm_group(S5TransitiveSubgroups$D5)); .pytuple(ct_zeta_order(t), .pyT(ct_shape(t))) })), "(5, (4, 4))")
  expect_identical(.pyrun(local({ ct_tolist(character_table(get_perm_group(S5TransitiveSubgroups$M20))) })), "[[1, 1, 1, 1, 1], [1, 1, -zeta4, -1, zeta4], [1, 1, -1, 1, -1], [1, 1, zeta4, -1, -zeta4], [4, -1, 0, 0, 0]]")
  expect_identical(.pyrun(local({ t <- character_table(get_perm_group(S5TransitiveSubgroups$M20)); .pytuple(ct_zeta_order(t), .pyT(ct_shape(t))) })), "(4, (5, 5))")
