  expect_identical(.pyrun(local({ t <- character_table(get_perm_group(S5TransitiveSubgroups$A5)); .pytuple(ct_zeta_order(t), .pyT(ct_shape(t))) })), "(5, (5, 5))")
  expect_identical(.pyrun(local({ ct_tolist(character_table(get_perm_group(S5TransitiveSubgroups$S5))) })), "[[1, 1, 1, 1, 1, 1, 1], [4, 2, 0, 1, -1, 0, -1], [5, 1, 1, -1, 1, -1, 0], [6, 0, -2, 0, 0, 0, 1], [5, -1, 1, -1, -1, 1, 0], [4, -2, 0, 1, 1, 0, -1], [1, -1, 1, 1, -1, -1, 1]]")
  expect_identical(.pyrun(local({ t <- character_table(get_perm_group(S5TransitiveSubgroups$S5)); .pytuple(ct_zeta_order(t), .pyT(ct_shape(t))) })), "(1, (7, 7))")
  expect_identical(.pyrun(local({ ct_tolist(character_table(get_perm_group(S6TransitiveSubgroups$C6))) })), "[[1, 1, 1, 1, 1, 1], [1, -1 - zeta3, zeta3, 1, -1 - zeta3, zeta3], [1, -zeta3, -1 - zeta3, -1, zeta3, 1 + zeta3], [1, -1, 1, -1, 1, -1], [1, zeta3, -1 - zeta3, 1, zeta3, -1 - zeta3], [1, 1 + zeta3, zeta3, -1, -1 - zeta3, -zeta3]]")
  expect_identical(.pyrun(local({ t <- character_table(get_perm_group(S6TransitiveSubgroups$C6)); .pytuple(ct_zeta_order(t), .pyT(ct_shape(t))) })), "(3, (6, 6))")
  expect_identical(.pyrun(local({ ct_tolist(character_table(get_perm_group(S6TransitiveSubgroups$S3))) })), "[[1, 1, 1], [1, 1, -1], [2, -1, 0]]")
