  expect_identical(.pyrun(local({ t <- character_table(get_perm_group(S6TransitiveSubgroups$D6)); .pytuple(ct_zeta_order(t), .pyT(ct_shape(t))) })), "(1, (6, 6))")
  expect_identical(.pyrun(local({ ct_tolist(character_table(get_perm_group(S6TransitiveSubgroups$A4))) })), "[[1, 1, 1, 1], [1, -1 - zeta3, zeta3, 1], [1, zeta3, -1 - zeta3, 1], [3, 0, 0, -1]]")
