test_that("character_table: orth matches SymPy", {
  expect_identical(.pyrun(local({ G <- get_perm_group(S1TransitiveSubgroups$S1); t <- ct_tolist(character_table(G)); .pytuple(sstr(.add(lapply(t, function(r) .pow(r[[1L]], S_Two)))) == as.character(group_order(G)), all(vapply(t[[1L]], function(v) identical(v$key, S_One$key), TRUE))) })), "(True, True)")
  expect_identical(.pyrun(local({ G <- get_perm_group(S2TransitiveSubgroups$S2); t <- ct_tolist(character_table(G)); .pytuple(sstr(.add(lapply(t, function(r) .pow(r[[1L]], S_Two)))) == as.character(group_order(G)), all(vapply(t[[1L]], function(v) identical(v$key, S_One$key), TRUE))) })), "(True, True)")
  expect_identical(.pyrun(local({ G <- get_perm_group(S3TransitiveSubgroups$A3); t <- ct_tolist(character_table(G)); .pytuple(sstr(.add(lapply(t, function(r) .pow(r[[1L]], S_Two)))) == as.character(group_order(G)), all(vapply(t[[1L]], function(v) identical(v$key, S_One$key), TRUE))) })), "(True, True)")
  expect_identical(.pyrun(local({ G <- get_perm_group(S3TransitiveSubgroups$S3); t <- ct_tolist(character_table(G)); .pytuple(sstr(.add(lapply(t, function(r) .pow(r[[1L]], S_Two)))) == as.character(group_order(G)), all(vapply(t[[1L]], function(v) identical(v$key, S_One$key), TRUE))) })), "(True, True)")
  expect_identical(.pyrun(local({ G <- get_perm_group(S4TransitiveSubgroups$C4); t <- ct_tolist(character_table(G)); .pytuple(sstr(.add(lapply(t, function(r) .pow(r[[1L]], S_Two)))) == as.character(group_order(G)), all(vapply(t[[1L]], function(v) identical(v$key, S_One$key), TRUE))) })), "(True, True)")
