  expect_identical(.pyrun(local({ G <- get_perm_group(S4TransitiveSubgroups$D4); t <- ct_tolist(character_table(G)); .pytuple(sstr(.add(lapply(t, function(r) .pow(r[[1L]], S_Two)))) == as.character(group_order(G)), all(vapply(t[[1L]], function(v) identical(v$key, S_One$key), TRUE))) })), "(True, True)")
